// Writes data/guides/index.ts with a static import per library guide, so the
// guides are bundled into the server build (no runtime filesystem reads).
// Runs automatically before `dev`, `build` and `test`.
import { readdirSync, writeFileSync } from "node:fs";
import path from "node:path";

const dir = path.join(process.cwd(), "data", "guides");
const files = readdirSync(dir)
  .filter((f) => f.endsWith(".json"))
  .sort();

const ident = (f: string) => "g_" + f.replace(/\.json$/, "").replace(/[^a-zA-Z0-9]/g, "_");
const lines = [
  "// Generated by scripts/gen-library-index.ts — do not edit.",
  ...files.map((f) => `import ${ident(f)} from "./${f}";`),
  "",
  `export const LIBRARY_GUIDES_RAW: unknown[] = [${files.map(ident).join(", ")}];`,
  "",
];
writeFileSync(path.join(dir, "index.ts"), lines.join("\n"));
console.log(`library index: ${files.length} guide(s)`);
